import React from "react";
import "../../style/segment.css";
import { useNavigate } from "react-router-dom";
import { Col, Row } from "react-bootstrap";
import BKDLogo from "../../assest/bkdlogo.png";

function CardSegment({ title, showAllSegemtnList, layerDetails, isLoading }) {
  const navigate = useNavigate();

  const handleViewDetails = (id) => {
    // Filter layerDetails to include only the clicked _id
    const selectedData = layerDetails
      .filter((item) => item._id === id)
      .map((item) => ({
        banner: item.bigBanner,
        title: item.title,
      }))[0]; // Get the first (and only) item in the filtered list

    console.log("Selected Data------>", selectedData);

    // Navigate and pass the selected banner and title in the state
    navigate(`/segment-detials/${id}`, { state: selectedData });
  };

  return (
    layerDetails?.length !== 0 ?
      <div className="card_segment my-4">
        {layerDetails.map((item) => (
          <div className="segment_img" key={item._id}>
            <img
              src={item.smallBanner || BKDLogo}
              onError={(e) => e.currentTarget.src = BKDLogo}
              alt={item.title}
              onClick={() => handleViewDetails(item._id)}
            />
          </div>
        ))}
      </div>
      : null
  );
}

export default CardSegment;
